SELECT
    ast.*,
    ast.capacity - ast.booked_count AS remaining,
    p.name AS service_name
FROM appointment_slots AS ast
INNER JOIN products AS p ON p.id = ast.service_id
WHERE ast.service_id = #{serviceId}
  AND ast.shop_id = #{shopId}
  AND ast.slot_date BETWEEN #{from} AND #{to}
ORDER BY ast.slot_date, ast.start_time

