mapper.update:
UPDATE appointment_slots
SET day_status = #{dayStatus},
    version = version + 1
WHERE service_id = #{serviceId}
  AND shop_id = #{shopId}
  AND slot_date = #{slotDate}

mapper.delete:
DELETE ast
FROM appointment_slots ast
WHERE ast.service_id = #{serviceId}
  AND ast.shop_id = #{shopId}
  AND ast.slot_date = #{slotDate}
  AND ast.booked_count = 0
  AND NOT EXISTS (
      SELECT 1 FROM order_appointment_slots oas WHERE oas.slot_id = ast.id
  )

mapper.update:
UPDATE appointment_slots ast
SET ast.day_status = 'CLOSED'
WHERE ast.service_id = #{serviceId}
  AND ast.shop_id = #{shopId}
  AND ast.slot_date = #{slotDate}
  AND ast.booked_count = 0
  AND EXISTS (
      SELECT 1 FROM order_appointment_slots oas WHERE oas.slot_id = ast.id
  )

