mapper.update:
UPDATE appointment_slots
SET end_time = #{endTime},
    capacity = #{capacity},
    day_status = 'OPEN',
    status = 'OPEN'
WHERE service_id = #{serviceId}
  AND slot_date = #{slotDate}
  AND start_time = #{startTime}
  AND booked_count = 0

UPDATE appointment_slots
SET capacity = #{capacity},
    version = version + 1
WHERE id = #{id}
  AND shop_id = #{shopId}
  AND status <> 'EXPIRED'
  AND booked_count <= #{capacity}

UPDATE appointment_slots
SET status = 'OPEN',
    version = version + 1
WHERE id = #{id}
  AND shop_id = #{shopId}
  AND status = 'CLOSED'
